-- Synthetic fixtures only; all pgTAP changes roll back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) select ('41000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'invite-'||n||'@example.test' from generate_series(1,8) n;
insert into public.responsible_accounts(user_id) values('41000000-0000-0000-0000-000000000001'),('41000000-0000-0000-0000-000000000002');
insert into public.passengers(id,user_id,name,default_daily_rate)
select ('42000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'41000000-0000-0000-0000-000000000001','Synthetic invite target '||n,10 from generate_series(1,8) n;
insert into public.passengers(id,user_id,name,default_daily_rate) values('42000000-0000-0000-0000-000000000009','41000000-0000-0000-0000-000000000002','Synthetic owner B target',10);
select ok(not has_table_privilege('authenticated','public.passenger_invites','INSERT'),'direct INSERT closed');
select ok(not has_table_privilege('authenticated','public.passenger_invites','UPDATE'),'direct UPDATE closed');
select ok(not has_table_privilege('authenticated','public.passenger_invites','DELETE'),'direct DELETE closed');
select ok(has_table_privilege('authenticated','public.passenger_invites','SELECT'),'own SELECT available with RLS');
select ok(not has_table_privilege('anon','public.passenger_invites','SELECT'),'anon cannot list');
select ok(not exists(select 1 from information_schema.columns where table_schema='public' and table_name='passenger_invites' and column_name='code'),'cleartext column removed');
select ok(not has_function_privilege('anon','public.create_passenger_invite(uuid,text)','EXECUTE'),'anon denied create_passenger_invite(uuid,text)');
select ok(has_function_privilege('authenticated','public.create_passenger_invite(uuid,text)','EXECUTE'),'authenticated granted create_passenger_invite(uuid,text)');
select ok(not exists(select 1 from pg_proc p, lateral aclexplode(p.proacl) a where p.oid='public.create_passenger_invite(uuid,text)'::regprocedure and a.grantee=0 and a.privilege_type='EXECUTE'),'PUBLIC denied create_passenger_invite(uuid,text)');
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.create_passenger_invite(uuid,text)'::regprocedure),'definer and safe path create_passenger_invite(uuid,text)');
select ok(not has_function_privilege('anon','public.revoke_passenger_invite(uuid)','EXECUTE'),'anon denied revoke_passenger_invite(uuid)');
select ok(has_function_privilege('authenticated','public.revoke_passenger_invite(uuid)','EXECUTE'),'authenticated granted revoke_passenger_invite(uuid)');
select ok(not exists(select 1 from pg_proc p, lateral aclexplode(p.proacl) a where p.oid='public.revoke_passenger_invite(uuid)'::regprocedure and a.grantee=0 and a.privilege_type='EXECUTE'),'PUBLIC denied revoke_passenger_invite(uuid)');
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.revoke_passenger_invite(uuid)'::regprocedure),'definer and safe path revoke_passenger_invite(uuid)');
select ok(not has_function_privilege('anon','public.redeem_passenger_invite(text)','EXECUTE'),'anon denied redeem_passenger_invite(text)');
select ok(has_function_privilege('authenticated','public.redeem_passenger_invite(text)','EXECUTE'),'authenticated granted redeem_passenger_invite(text)');
select ok(not exists(select 1 from pg_proc p, lateral aclexplode(p.proacl) a where p.oid='public.redeem_passenger_invite(text)'::regprocedure and a.grantee=0 and a.privilege_type='EXECUTE'),'PUBLIC denied redeem_passenger_invite(text)');
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.redeem_passenger_invite(text)'::regprocedure),'definer and safe path redeem_passenger_invite(text)');
set local role authenticated;
set local request.jwt.claim.sub='41000000-0000-0000-0000-000000000001';
select lives_ok($$select public.create_passenger_invite('42000000-0000-0000-0000-000000000001',repeat('a',64))$$,'owner creates secure invite');
select is((select expires_at-created_at from public.passenger_invites),interval '168 hours','exact seven days in database');
select is((select token_hash from public.passenger_invites),encode(extensions.digest(repeat('a',64),'sha256'),'hex'),'only SHA256 hash stored');
select ok((select token_hash<>repeat('a',64) from public.passenger_invites),'raw token absent');
select lives_ok($$select public.create_passenger_invite('42000000-0000-0000-0000-000000000001',repeat('b',64))$$,'replacement invitation succeeds');
select is((select count(*) from public.passenger_invites where not used and revoked_at is null),1::bigint,'only one pending');
select ok((select revoked_at is not null from public.passenger_invites where token_hash=encode(extensions.digest(repeat('a',64),'sha256'),'hex')),'replacement revokes predecessor');
select throws_ok($$select public.create_passenger_invite('42000000-0000-0000-0000-000000000002','weak')$$,'P0001','INVITE_INVALID','short tokens rejected');
select throws_ok($$select public.redeem_passenger_invite(repeat('b',64))$$,'23514','ACCOUNT_INCOMPATIBLE','owner cannot redeem');
select lives_ok($$select public.create_passenger_invite('42000000-0000-0000-0000-000000000002',repeat('c',64))$$,'create revocation fixture');
select lives_ok($$select public.revoke_passenger_invite((select id from public.passenger_invites where passenger_id='42000000-0000-0000-0000-000000000002'))$$,'owner revokes own');
select lives_ok($$select public.revoke_passenger_invite((select id from public.passenger_invites where passenger_id='42000000-0000-0000-0000-000000000002'))$$,'revocation idempotent');
set local request.jwt.claim.sub='41000000-0000-0000-0000-000000000002';
select is((select count(*) from public.passenger_invites),0::bigint,'foreign owner sees no invites');
do $$ begin perform public.create_passenger_invite('42000000-0000-0000-0000-000000000009',repeat('e',64)); end $$;
select throws_ok($$select public.create_passenger_invite('42000000-0000-0000-0000-000000000001',repeat('d',64))$$,'42501','INVITE_INVALID','foreign owner cannot create for target');
reset role;
-- Privileged cross-owner fixture still rejected by composite FK, independent of RPC.
select throws_ok($$insert into public.passenger_invites(passenger_id,owner_user_id,token_hash) values('42000000-0000-0000-0000-000000000003','41000000-0000-0000-0000-000000000002',repeat('d',64))$$,'23503',null,'composite FK rejects mismatched owner');
insert into public.passenger_invites(passenger_id,owner_user_id,token_hash,created_at,expires_at)
values('42000000-0000-0000-0000-000000000003','41000000-0000-0000-0000-000000000001',encode(extensions.digest(repeat('d',64),'sha256'),'hex'),now()-interval '8 days',now()-interval '1 day');
create temporary table invite_ids as select id from public.passenger_invites where passenger_id='42000000-0000-0000-0000-000000000001' and revoked_at is null;
grant select on invite_ids to authenticated;
set local role authenticated;
set local request.jwt.claim.sub='41000000-0000-0000-0000-000000000002';
select throws_ok($$select public.revoke_passenger_invite((select id from invite_ids))$$,'42501','INVITE_INVALID','foreign owner cannot revoke');
set local request.jwt.claim.sub='41000000-0000-0000-0000-000000000003';
select is((select count(*) from public.passenger_invites),0::bigint,'unlinked cannot enumerate tokens');
select throws_ok($$select public.redeem_passenger_invite(repeat('0',64))$$,'P0001','INVITE_INVALID','unknown token rejected');
select throws_ok($$select public.redeem_passenger_invite('bad')$$,'P0001','INVITE_INVALID','malformed token rejected');
select throws_ok($$select public.redeem_passenger_invite(repeat('a',64))$$,'P0001','INVITE_REVOKED','replacement predecessor unusable');
select throws_ok($$select public.redeem_passenger_invite(repeat('c',64))$$,'P0001','INVITE_REVOKED','revoked invite unusable');
select throws_ok($$select public.redeem_passenger_invite(repeat('d',64))$$,'P0001','INVITE_EXPIRED','expired invite unusable');
select is((select count(*) from public.passenger_accounts),0::bigint,'failed redemptions create no link');
select lives_ok($$select public.redeem_passenger_invite(repeat('b',64))$$,'valid token redeems');
select is((select passenger_id from public.passenger_accounts where user_id=auth.uid()),'42000000-0000-0000-0000-000000000001'::uuid,'correct target linked');
select ok(not public.is_responsible(),'redemption does not grant responsibility');
select throws_ok($$select public.redeem_passenger_invite(repeat('b',64))$$,'23514','ACCOUNT_INCOMPATIBLE','linked user cannot redeem again');
select throws_ok($$select public.redeem_passenger_invite(repeat('e',64))$$,'23514','ACCOUNT_INCOMPATIBLE','linked owner A passenger cannot consume owner B invitation');
select throws_ok($$select public.revoke_passenger_invite((select id from invite_ids))$$,'42501','ACCOUNT_INCOMPATIBLE','passenger cannot revoke');
select throws_ok($$select public.create_passenger_invite('42000000-0000-0000-0000-000000000004',repeat('e',64))$$,'42501','ACCOUNT_INCOMPATIBLE','passenger cannot create');
set local request.jwt.claim.sub='41000000-0000-0000-0000-000000000004';
select throws_ok($$select public.redeem_passenger_invite(repeat('b',64))$$,'P0001','INVITE_USED','another user cannot reuse');
select is((select count(*) from public.passenger_accounts where user_id=auth.uid()),0::bigint,'reuse creates no second link');
set local request.jwt.claim.sub='';
select throws_ok($$select public.redeem_passenger_invite(repeat('b',64))$$,'42501','SESSION_REQUIRED','RPC checks missing UID internally');
reset role;
select ok((select used and used_at is not null and used_by='41000000-0000-0000-0000-000000000003' from public.passenger_invites where id=(select id from invite_ids)),'coherent atomic consumption');
select throws_ok($$update public.passenger_invites set revoked_at=now() where id=(select id from invite_ids)$$,'23514',null,'used and revoked states cannot coexist');
select throws_ok($$update public.passenger_invites set expires_at=expires_at+interval '1 day' where id=(select id from invite_ids)$$,'23514',null,'expiration cannot violate seven days');
set local role authenticated;
set local request.jwt.claim.sub='41000000-0000-0000-0000-000000000001';
select throws_ok($$select public.revoke_passenger_invite((select id from invite_ids))$$,'P0001','INVITE_USED','used invitation cannot be revoked');
select throws_ok($$select public.create_passenger_invite('42000000-0000-0000-0000-000000000001',repeat('e',64))$$,'23514','ACCOUNT_INCOMPATIBLE','cannot invite an already linked target');
reset role;
set local role anon;
select throws_ok($$select public.redeem_passenger_invite(repeat('b',64))$$,'42501',null,'anon execution rejected');
select throws_ok($$select public.create_passenger_invite('42000000-0000-0000-0000-000000000004',repeat('e',64))$$,'42501',null,'anon create rejected');
select throws_ok($$select public.revoke_passenger_invite((select id from invite_ids))$$,'42501',null,'anon revoke rejected');
reset role;
select * from finish();
rollback;
